import java.util.concurrent.CompletableFuture;
import java.util.stream.Collectors;

public class Command {
    public static void register(CommandDispatcher<ServerCommandSource> dispatcher) {
        dispatcher.register(CommandManager.literal(MCA.MOD_ID)
                .then(register("propose").then(CommandManager.argument("target", EntityArgumentType.player()).executes(Command::propose)))
                .then(register("accept").then(CommandManager.argument("target", EntityArgumentType.player()).executes(Command::accept)))
                .then(register("proposals", Command::displayProposal))
                .then(register("procreate", Command::procreate))
                .then(register("separate", Command::separate))
                .then(register("reject").then(CommandManager.argument("target", EntityArgumentType.player()).executes(Command::reject)))
                .then(register("editor", Command::editor))
                .then(register("destiny", Command::destiny))
                .then(register("mail", Command::mail))
                .then(register("verify").then(CommandManager.argument("email", StringArgumentType.greedyString()).executes(Command::verify)))
                .then(register("chatAI")
                        .requires(p -> p.hasPermissionLevel(2) || p.getServer().isSingleplayer())
                        .executes(Command::chatAIHelp)
                        .then(CommandManager.literal("disable")
                                .executes(Command::disableChatAI))
                        .then(CommandManager.literal("default")
                                .executes(c -> Command.enableChatAI(c, "default", (new Config()).villagerChatAIEndpoint, "")))
                        .then(CommandManager.literal("player2")
                                .executes(Command::setupPlayer2))
                        .then(register("inworldAI")
                                .requires(p -> p.hasPermissionLevel(2) || p.getServer().isSingleplayer())
                                .then(register("keys")
                                        .then(CommandManager.argument("api_key", StringArgumentType.string())
                                                .executes(c -> Command.inworldAIKey(c.getArgument("api_key", String.class)))))
                                .then(register("addCharacter")
                                        .then(CommandManager.argument("villager_name", StringArgumentType.string())
                                                .then(CommandManager.argument("character_endpoint", StringArgumentType.string())
                                                        .executes(c -> Command.inworldAICharacter(c, c.getArgument("villager_name", String.class), c.getArgument("character_endpoint", String.class)))
                                                )
                                        )
                                )
                        )
                        .then(CommandManager.argument("model", StringArgumentType.string())
                                .executes(c -> Command.enableChatAI(c, c.getArgument("model", String.class), (new Config()).villagerChatAIEndpoint, ""))
                                .then(CommandManager.argument("endpoint", StringArgumentType.string())
                                        .executes(c -> Command.enableChatAI(c, c.getArgument("model", String.class), c.getArgument("endpoint", String.class), ""))
                                        .then(CommandManager.argument("token", StringArgumentType.string())
                                                .executes(c -> Command.enableChatAI(c, c.getArgument("model", String.class), c.getArgument("endpoint", String.class), c.getArgument("token", String.class)))))))
                .then(register("tts")
                        .requires(p -> p.getServer().isSingleplayer())
                        .then(CommandManager.literal("default").executes(ctx -> ttsEnable(ctx, "default")))
                        .then(CommandManager.literal("elevenlabs").executes(ctx -> ttsEnable(ctx, "elevenlabs")))
                        .then(CommandManager.literal("realtime").executes(ctx -> ttsEnable(ctx, "realtime")))
                        .then(CommandManager.literal("disable").executes(Command::ttsDisable))
                )
        );
    }

    private static int chatAIHelp(CommandContext<ServerCommandSource> ctx) {
        return enableChatAI(ctx, (new Config()).villagerChatAIModel, (new Config()).villagerChatAIEndpoint, (new Config()).villagerChatAIToken);
    }

    private static int inworldAIKey(String apiKey) {
        Config.getInstance().inworldAIToken = apiKey;
        Config.getInstance().save();
        return 0;
    }

    private static int inworldAICharacter(CommandContext<ServerCommandSource> ctx, String name, String endpoint) {
        ServerPlayerEntity player = ctx.getSource().getPlayer();
        Optional<VillagerEntityMCA> optionalVillager = ChatAI.findVillagerInArea(player, name);
        optionalVillager.ifPresent(v -> {
            Config.getInstance().inworldAIResourceNames.put(v.getUuid(), endpoint);
            ChatAI.clearStrategy(v.getUuid());
            Config.getInstance().save();
        });
        return 0;
    }

    private static int enableChatAI(CommandContext<ServerCommandSource> ctx, String model, String endpoint, String token) {
        Config.getInstance().enableVillagerChatAI = true;
        Config.getInstance().villagerChatAIModel = model;
        Config.getInstance().villagerChatAIEndpoint = endpoint;
        Config.getInstance().villagerChatAIToken = token;
        Config.getInstance().save();

        if (model.equals("default")) {
            sendMessage(ctx, Text.translatable("mca.ai_help").styled(s -> s
                    .withClickEvent(new ClickEvent(ClickEvent.Action.OPEN_URL, "https://github.com/Luke100000/minecraft-comes-alive/wiki/GPT3-based-conversations"))
            ));
        } else {
            sendMessage(ctx, "command.chat_ai.enabled");
        }
        return 0;
    }

    private static int disableChatAI(CommandContext<ServerCommandSource> c) {
        Config.getInstance().enableVillagerChatAI = false;
        Config.getInstance().save();
        sendMessage(c, "command.chat_ai.disabled");
        return 0;
    }

    private static int setupPlayer2(CommandContext<ServerCommandSource> ctx) {
        // Use player2s endpoint
        Config.getInstance().enableVillagerChatAI = true;
        Config.getInstance().villagerChatAIModel = "player2";
        Config.getInstance().villagerChatAIEndpoint = "http://127.0.0.1:4315/v1/chat/completions";
        Config.getInstance().villagerChatAIToken = "";
        Config.getInstance().villagerChatAIUseTools = true;

        // And turn on TTS
        Config.getInstance().enableOnlineTTS = true;
        Config.getInstance().onlineTTSModel = "player2";

        Config.getInstance().save();

        sendMessage(ctx, Text.translatable("command.chat_ai.player2").styled(s -> s
                .withClickEvent(new ClickEvent(ClickEvent.Action.OPEN_URL, "https://player2.game/"))));
        return 0;
    }

    private static int ttsEnable(CommandContext<ServerCommandSource> ctx, String model) {
        Config.getInstance().enableOnlineTTS = true;
        Config.getInstance().onlineTTSModel = model;
        Config.getInstance().save();
        sendMessage(ctx, Text.translatable("command.tts.enabled." + model));
        return 0;
    }

    private static int ttsDisable(CommandContext<ServerCommandSource> ctx) {
        Config.getInstance().enableOnlineTTS = false;
        Config.getInstance().save();

        return 0;
    }

    private static int editor(CommandContext<ServerCommandSource> ctx) {
        ServerPlayerEntity player = ctx.getSource().getPlayer();
        if (player == null) {
            return 1;
        }
        if (ctx.getSource().hasPermissionLevel(2) || Config.getInstance().allowFullPlayerEditor) {
            NetworkHandler.sendToPlayer(new OpenGuiRequest(OpenGuiRequest.Type.VILLAGER_EDITOR, player), player);
            return 0;
        } else if (Config.getInstance().allowLimitedPlayerEditor) {
            NetworkHandler.sendToPlayer(new OpenGuiRequest(OpenGuiRequest.Type.LIMITED_VILLAGER_EDITOR, player), player);
            return 0;
        } else {
            sendMessage(ctx, Text.translatable("command.no_permission").formatted(Formatting.RED));
            return 1;
        }
    }

    private static int destiny(CommandContext<ServerCommandSource> ctx) {
        if (ctx.getSource().hasPermissionLevel(2) || Config.getInstance().allowDestinyCommandOnce) {
            ServerPlayerEntity player = ctx.getSource().getPlayer();
            if (player != null && !PlayerSaveData.get(player).isEntityDataSet() || Config.getInstance().allowDestinyCommandMoreThanOnce) {
                ServerInteractionManager.launchDestiny(player);
                return 0;
            } else {
                sendMessage(ctx, Text.translatable("command.only_one_destiny").formatted(Formatting.RED));
                return 1;
            }
        } else {
            sendMessage(ctx, Text.translatable("command.no_permission").formatted(Formatting.RED));
            return 1;
        }
    }

    private static int mail(CommandContext<ServerCommandSource> ctx) {
        ServerPlayerEntity player = ctx.getSource().getPlayer();
        if (player == null) {
            return 1;
        }
        PlayerSaveData data = PlayerSaveData.get(player);
        if (data.hasMail()) {
            while (data.hasMail()) {
                player.getInventory().offerOrDrop(data.getMail());
            }
        } else {
            sendMessage(ctx, "command.no_mail");
        }
        return 0;
    }

    private static int verify(CommandContext<ServerCommandSource> ctx) {
        ServerPlayerEntity player = ctx.getSource().getPlayer();

        CompletableFuture.runAsync(() -> {
            // build http request
            Map<String, String> params = new HashMap<>();
            params.put("email", StringArgumentType.getString(ctx, "email"));
            assert player != null;
            params.put("player", player.getName().getString());

            // encode and create url
            String encodedURL = params.keySet().stream()
                    .map(key -> key + "=" + URLEncoder.encode(params.get(key), StandardCharsets.UTF_8))
                    .collect(Collectors.joining("&", Config.getInstance().villagerChatAIEndpoint.replace("v1/mca/chat", "v1/mca/verify") + "?", ""));

            String request = OpenAIChatAI.verify(encodedURL);

            if (request.equals("success")) {
                sendMessage(ctx, Text.translatable("command.verify.success").formatted(Formatting.GREEN));
            } else if (request.equals("failed")) {
                sendMessage(ctx, Text.translatable("command.verify.failed").formatted(Formatting.RED));
            } else {
                sendMessage(ctx, Text.translatable("command.verify.crashed").formatted(Formatting.RED));
            }
        });
        return 0;
    }

    private static int propose(CommandContext<ServerCommandSource> ctx) throws CommandSyntaxException {
        ServerPlayerEntity target = EntityArgumentType.getPlayer(ctx, "target");
        ServerInteractionManager.getInstance().sendProposal(ctx.getSource().getPlayer(), target);

        return 0;
    }

    private static int accept(CommandContext<ServerCommandSource> ctx) throws CommandSyntaxException {
        ServerPlayerEntity target = EntityArgumentType.getPlayer(ctx, "target");
        ServerInteractionManager.getInstance().acceptProposal(ctx.getSource().getPlayer(), target);
        return 0;
    }

    private static int displayProposal(CommandContext<ServerCommandSource> ctx) {
        ServerInteractionManager.getInstance().listProposals(ctx.getSource().getPlayer());

        return 0;
    }

    private static int procreate(CommandContext<ServerCommandSource> ctx) {
        ServerInteractionManager.getInstance().procreate(ctx.getSource().getPlayer());
        return 0;
    }

    private static int separate(CommandContext<ServerCommandSource> ctx) {
        ServerInteractionManager.getInstance().endMarriage(ctx.getSource().getPlayer());
        return 0;
    }

    private static int reject(CommandContext<ServerCommandSource> ctx) throws CommandSyntaxException {
        ServerPlayerEntity target = EntityArgumentType.getPlayer(ctx, "target");
        ServerInteractionManager.getInstance().rejectProposal(ctx.getSource().getPlayer(), target);
        return 0;
    }


    private static ArgumentBuilder<ServerCommandSource, ?> register(String name, com.mojang.brigadier.Command<ServerCommandSource> cmd) {
        return CommandManager.literal(name).requires(cs -> cs.hasPermissionLevel(0)).executes(cmd);
    }

    private static ArgumentBuilder<ServerCommandSource, ?> register(String name) {
        return CommandManager.literal(name).requires(cs -> cs.hasPermissionLevel(0));
    }

    private static void sendMessage(CommandContext<ServerCommandSource> ctx, String message) {
        sendMessage(ctx, Text.translatable(message));
    }

    private static void sendMessage(CommandContext<ServerCommandSource> ctx, Text message) {
        ServerPlayerEntity player = ctx.getSource().getPlayer();
        if (player != null) {
            player.sendMessage(message);
        }
    }
}

package net.mca.server.world.data;

import net.mca.entity.ai.relationship.EntityRelationship;
import net.mca.entity.ai.relationship.Gender;
import net.mca.entity.ai.relationship.RelationshipState;
import net.mca.util.NbtHelper;
import net.mca.util.WorldUtils;
import net.minecraft.entity.Entity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.server.world.ServerWorld;
import net.minecraft.util.Util;
import net.minecraft.world.PersistentState;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.*;
import java.util.stream.Stream;

public class FamilyTree extends PersistentState {
    private static final String DATA_ID = "MCA-FamilyTree";

    private final Map<UUID, FamilyTreeNode> entries;

    public static FamilyTree get(ServerWorld world) {
        return WorldUtils.loadData(world.getServer().getOverworld(), FamilyTree::new, FamilyTree::new, DATA_ID);
    }

    FamilyTree(ServerWorld world) {
        entries = new HashMap<>();
    }

    FamilyTree(NbtCompound nbt) {
        entries = NbtHelper.toMap(nbt, UUID::fromString, (id, element) -> new FamilyTreeNode(this, id, (NbtCompound)element));

        // Fixing the shift in relationships introduces by the promised update
        // TODO the moment this code here causes any porting errors, remove it. By that time no old saves should exist anyways.
        UUID uuid = UUID.fromString("12341234-1234-1234-1234-123412341234");
        if (!entries.containsKey(uuid)) {
            entries.put(uuid, createEntry(uuid, "debug", Gender.NEUTRAL, false));
            markDirty();

            entries.values().forEach(e -> {
                FamilyTreeNode partner = entries.get(e.partner());
                boolean partnerIsPlayer = partner != null && partner.isPlayer();
                if (e.getRelationshipState() == RelationshipState.ENGAGED && partnerIsPlayer == e.isPlayer()) {
                    //this is a villager-villager or player-player relationship. They do not have engagement
                    e.setRelationshipState(RelationshipState.MARRIED_TO_VILLAGER);
                }
                if (e.getRelationshipState() == RelationshipState.MARRIED_TO_VILLAGER && partnerIsPlayer) {
                    //The partner is not a villager
                    e.setRelationshipState(RelationshipState.MARRIED_TO_PLAYER);
                }
                if (e.getRelationshipState() == RelationshipState.MARRIED_TO_PLAYER && !partnerIsPlayer) {
                    //The partner is not a player
                    e.setRelationshipState(RelationshipState.WIDOW);
                }
            });
        }
    }

    @Override
    public NbtCompound writeNbt(NbtCompound nbt) {
        return NbtHelper.fromMap(nbt, entries, UUID::toString, FamilyTreeNode::save);
    }

    public Optional<FamilyTreeNode> getOrEmpty(@Nullable UUID id) {
        return id == null ? Optional.empty() : Optional.ofNullable(entries.get(id));
    }

    public Stream<FamilyTreeNode> getAllWithName(String name) {
        return entries.values().stream().filter(n -> n.getName().toLowerCase(Locale.ROOT).equals(name.toLowerCase(Locale.ROOT)));
    }

    @NotNull
    public FamilyTreeNode getOrCreate(Entity entity) {
        return entries.computeIfAbsent(entity.getUuid(), uuid -> createEntry(
                entity.getUuid(),
                entity.getName().getString(),
                EntityRelationship.of(entity).map(EntityRelationship::getGender).orElse(Gender.MALE),
                entity instanceof PlayerEntity));
    }

    public void remove(UUID id) {
        entries.remove(id);
        markDirty();
    }

    @NotNull
    public FamilyTreeNode getOrCreate(UUID id, String name, Gender gender) {
        return getOrCreate(id, name, gender, false);
    }

    @NotNull
    public FamilyTreeNode getOrCreate(UUID id, String name, Gender gender, boolean isPlayer) {
        return entries.computeIfAbsent(id, uuid -> createEntry(uuid, name, gender, isPlayer));
    }

    private FamilyTreeNode createEntry(UUID uuid, String name, Gender gender, boolean isPlayer) {
        markDirty();
        return new FamilyTreeNode(this,
                uuid,
                name,
                isPlayer,
                gender,
                Util.NIL_UUID,
                Util.NIL_UUID
        );
    }
}

package net.mca.server.world.data;

import net.mca.MCA;
import net.mca.entity.ai.relationship.EntityRelationship;
import net.mca.entity.ai.relationship.Gender;
import net.mca.entity.ai.relationship.RelationshipState;
import net.mca.util.NbtHelper;
import net.minecraft.entity.Entity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;
import net.minecraft.registry.Registries;
import net.minecraft.text.MutableText;
import net.minecraft.text.Text;
import net.minecraft.util.Identifier;
import net.minecraft.util.Util;
import net.minecraft.village.VillagerProfession;
import org.jetbrains.annotations.Nullable;

import java.io.Serial;
import java.io.Serializable;
import java.util.HashSet;
import java.util.Optional;
import java.util.Set;
import java.util.UUID;
import java.util.function.Function;
import java.util.stream.Stream;

public final class FamilyTreeNode implements Serializable {
    @Serial
    private static final long serialVersionUID = -7307057982785253721L;

    private final boolean isPlayer;

    private Gender gender;

    private String name;
    private String profession = Registries.VILLAGER_PROFESSION.getId(VillagerProfession.NONE).toString();

    private final UUID id;

    private UUID father;
    private UUID mother;

    private UUID partner = Util.NIL_UUID;
    private RelationshipState relationshipState = RelationshipState.SINGLE;

    private boolean deceased;

    private final Set<UUID> children = new HashSet<>();

    private transient final FamilyTree rootNode;

    public FamilyTreeNode(FamilyTree rootNode, UUID id, String name, boolean isPlayer, Gender gender, UUID father, UUID mother) {
        this.rootNode = rootNode;
        this.id = id;
        this.name = name;
        this.isPlayer = isPlayer;
        this.gender = gender;
        this.father = father;
        this.mother = mother;
    }

    public FamilyTreeNode(FamilyTree rootNode, UUID id, NbtCompound nbt) {
        this(
                rootNode,
                id,
                nbt.getString("name"),
                nbt.getBoolean("isPlayer"),
                Gender.byId(nbt.getInt("gender")),
                nbt.getUuid("father"),
                nbt.getUuid("mother")
        );
        children.addAll(NbtHelper.toList(nbt.getList("children", NbtElement.COMPOUND_TYPE), c -> ((NbtCompound)c).getUuid("uuid")));
        profession = nbt.getString("profession");
        deceased = nbt.getBoolean("isDeceased");
        if (nbt.containsUuid("spouse")) {
            partner = nbt.getUuid("spouse");
        }
        relationshipState = RelationshipState.byId(nbt.getInt("marriageState"));
    }

    public UUID id() {
        return id;
    }

    private void markDirty() {
        if (rootNode != null) {
            rootNode.markDirty();
        }
    }

    public boolean isDeceased() {
        return deceased;
    }

    public void setDeceased(boolean deceased) {
        this.deceased = deceased;
        markDirty();
    }

    public void setName(String name) {
        this.name = name;
        markDirty();
    }

    public String getName() {
        return name;
    }

    public void setProfession(VillagerProfession profession) {
        this.profession = Registries.VILLAGER_PROFESSION.getId(profession).toString();
        markDirty();
    }

    public VillagerProfession getProfession() {
        return Registries.VILLAGER_PROFESSION.get(getProfessionId());
    }

    public Identifier getProfessionId() {
        return Identifier.tryParse(profession);
    }

    public String getProfessionName() {
        String professionName = (
                getProfessionId().getNamespace().equalsIgnoreCase("minecraft") ?
                        (getProfessionId().getPath().equals("none") ? "mca.none" : getProfessionId().getPath()) :
                        getProfessionId().toString()
        ).replace(":", ".");

        return MCA.isBlankString(professionName) ? "mca.none" : professionName;
    }

    public MutableText getProfessionText() {
        return Text.translatable("entity.minecraft.villager." + getProfessionName());
    }

    public boolean isPlayer() {
        return isPlayer;
    }

    public Gender gender() {
        return gender;
    }

    public UUID father() {
        return father;
    }

    public UUID mother() {
        return mother;
    }

    /**
     * Id of the last this entity's most recent partner.
     */
    public UUID partner() {
        return partner;
    }

    public RelationshipState getRelationshipState() {
        return relationshipState;
    }

    //debug usage only
    public void setRelationshipState(RelationshipState relationshipState) {
        this.relationshipState = relationshipState;
    }

    public void updatePartner(@Nullable Entity newPartner, @Nullable RelationshipState state) {
        //cancel relationship with previous partner
        if (!this.partner.equals(Util.NIL_UUID) && (newPartner == null || !this.partner.equals(newPartner.getUuid()))) {
            getRoot().getOrEmpty(this.partner).ifPresent(n -> {
                n.partner = Util.NIL_UUID;
                n.relationshipState = RelationshipState.SINGLE;
            });
        }

        this.partner = newPartner == null ? Util.NIL_UUID : newPartner.getUuid();
        this.relationshipState = state == null && newPartner == null ? RelationshipState.SINGLE : state;

        // ensure the family tree has an entry
        if (newPartner != null) {
            rootNode.getOrCreate(newPartner);
        }

        rootNode.markDirty();
    }

    public void updatePartner(FamilyTreeNode spouse) {
        this.partner = spouse.id();
        this.relationshipState = spouse.isPlayer ? RelationshipState.MARRIED_TO_PLAYER : RelationshipState.MARRIED_TO_VILLAGER;
        markDirty();
    }

    public Set<UUID> children() {
        return children;
    }

    public Stream<UUID> streamChildren() {
        return children.stream().filter(FamilyTreeNode::isValid);
    }

    public Stream<UUID> streamParents() {
        return Stream.of(father(), mother()).filter(FamilyTreeNode::isValid);
    }

    /**
     * All persons who share at least one common parent
     */
    public Set<UUID> siblings() {
        Set<UUID> siblings = new HashSet<>();

        streamParents().forEach(parent -> getRoot().getOrEmpty(parent).ifPresent(p -> gatherChildren(p, siblings, 1)));

        return siblings;
    }

    public Stream<UUID> getChildren() {
        return getRelatives(0, 1);
    }

    // returns indirect relatives like siblings and their respective family
    // potential slow for large families, getRelatives() is preferred if indirect family members are not relevant
    public Stream<UUID> getAllRelatives(int depth) {
        Set<UUID> family = new HashSet<>();

        //recursive family fetching
        Set<UUID> todo = new HashSet<>();
        todo.add(id);
        for (int d = 0; d < depth; d++) {
            Set<UUID> nextTodo = new HashSet<>();
            for (UUID uuid : todo) {
                if (!family.contains(uuid)) {
                    rootNode.getOrEmpty(uuid).ifPresent(node -> {
                        family.add(uuid);

                        //add parents and children
                        node.streamParents().forEach(nextTodo::add);
                        node.streamChildren().forEach(nextTodo::add);
                    });
                }
            }
            todo = nextTodo;
        }

        //the caller is not meant
        family.remove(id);

        return family.stream();
    }

    // returns all direct relatives (parents, grandparents, children, grandchildren)
    public Stream<UUID> getRelatives(int parentDepth, int childrenDepth) {
        Set<UUID> family = new HashSet<>();

        //fetch parents and children
        gatherParents(this, family, parentDepth);
        gatherChildren(this, family, childrenDepth);

        //and the caller is not meant either
        family.remove(id);

        return family.stream();
    }

    public boolean isRelative(UUID with) {
        return getAllRelatives(9).anyMatch(with::equals);
    }

    public Stream<FamilyTreeNode> getParents() {
        return lookup(streamParents());
    }

    /**
     * All persons who share at least one common parent
     */
    public Stream<FamilyTreeNode> getSiblings() {
        return lookup(siblings().stream());
    }

    public Stream<FamilyTreeNode> lookup(Stream<UUID> uuids) {
        return uuids.map(getRoot()::getOrEmpty).filter(Optional::isPresent).map(Optional::get);
    }

    public boolean isParent(UUID id) {
        return streamParents().anyMatch(parent -> parent.equals(id));
    }

    public boolean isGrandParent(UUID id) {
        return getParents().anyMatch(parent -> parent.isParent(id));
    }

    public boolean isUncle(UUID id) {
        return getParents().flatMap(parent -> parent.siblings().stream()).distinct().anyMatch(id::equals);
    }

    public void addChild(UUID child) {
        children.add(child);
    }

    public FamilyTree getRoot() {
        return rootNode;
    }

    public boolean replaceParents(EntityRelationship one, EntityRelationship two) {
        return replaceParents(Stream.of(one.getFamilyEntry(), two.getFamilyEntry()));
    }

    public boolean replaceParents(FamilyTreeNode one, Optional<FamilyTreeNode> two) {
        return replaceParents(Stream.concat(Stream.of(one), two.stream()));
    }

    public boolean replaceParents(Stream<FamilyTreeNode> parents) {
        boolean result = clearParents();
        return parents.map(this::assignParent).reduce(result, (changed, parentChanged) -> changed | parentChanged);
    }

    public boolean assignParent(FamilyTreeNode parent) {
        int parents = (isValid(father) ? 1 : 0) + (isValid(mother) ? 1 : 0);

        if (parents == 1) {
            //fill up last slot, independent on gender
            if (!isValid(father)) {
                return setFather(parent);
            } else if (!isValid(mother)) {
                return setMother(parent);
            }
        } else {
            //fill up gender respective slot
            if (parent.gender() == Gender.MALE) {
                return setFather(parent);
            } else {
                return setMother(parent);
            }
        }
        return true;
    }

    public boolean clearParents() {
        return removeFather() | removeMother();
    }

    public boolean setFather(FamilyTreeNode parent) {
        father = parent.id();
        parent.children().add(id);
        markDirty();
        return true;
    }

    public boolean setMother(FamilyTreeNode parent) {
        mother = parent.id();
        parent.children().add(id);
        markDirty();
        return true;
    }

    public boolean removeFather() {
        if (isValid(father)) {
            rootNode.getOrEmpty(father).ifPresent(e -> e.children.remove(this.id));
            father = Util.NIL_UUID;
            markDirty();
            return true;
        } else {
            return false;
        }
    }

    public boolean removeMother() {
        if (isValid(mother)) {
            rootNode.getOrEmpty(mother).ifPresent(e -> e.children.remove(this.id));
            mother = Util.NIL_UUID;
            markDirty();
            return true;
        } else {
            return false;
        }
    }

    public void setGender(Gender gender) {
        this.gender = gender;
        markDirty();
    }

    // entries with these conditions are usually generated
    public boolean probablyGenerated() {
        return mother.equals(Util.NIL_UUID) && father.equals(Util.NIL_UUID) && children.size() == 1 && deceased && !isPlayer();
    }

    // true if there is at least one non-generated relative
    public boolean willBeRemembered() {
        if (!children.isEmpty()) {
            return true;
        }
        if (!partner.equals(Util.NIL_UUID)) {
            return true;
        }
        return !getParents().allMatch(FamilyTreeNode::probablyGenerated);
    }

    public static boolean isValid(@Nullable UUID uuid) {
        return uuid != null && !Util.NIL_UUID.equals(uuid);
    }

    private static void gatherParents(FamilyTreeNode current, Set<UUID> family, int depth) {
        gather(current, family, depth, FamilyTreeNode::streamParents);
    }

    private static void gatherChildren(FamilyTreeNode current, Set<UUID> family, int depth) {
        gather(current, family, depth, FamilyTreeNode::streamChildren);
    }

    private static void gather(@Nullable FamilyTreeNode entry, Set<UUID> output, int depth, Function<FamilyTreeNode, Stream<UUID>> walker) {
        if (entry == null || depth <= 0) {
            return;
        }
        walker.apply(entry).forEach(id -> {
            if (!Util.NIL_UUID.equals(id)) {
                output.add(id); //zero UUIDs are no real members
            }
            if (depth > 1) {
                entry.getRoot().getOrEmpty(id).ifPresent(e -> gather(e, output, depth - 1, walker));
            }
        });
    }

    public NbtCompound save() {
        NbtCompound nbt = new NbtCompound();
        nbt.putString("name", name);
        nbt.putBoolean("isPlayer", isPlayer);
        nbt.putBoolean("isDeceased", deceased);
        nbt.putInt("gender", gender.getId());
        nbt.putUuid("father", father);
        nbt.putUuid("mother", mother);
        nbt.putUuid("spouse", partner);
        nbt.putInt("marriageState", relationshipState.ordinal());
        nbt.put("children", NbtHelper.fromList(children, child -> {
            NbtCompound n = new NbtCompound();
            n.putUuid("uuid", child);
            return n;
        }));
        return nbt;
    }
}

package net.mca.server.world.data;

import net.mca.Config;
import net.mca.advancement.criterion.CriterionMCA;
import net.mca.cobalt.network.NetworkHandler;
import net.mca.entity.EntitiesMCA;
import net.mca.entity.VillagerEntityMCA;
import net.mca.entity.ai.relationship.EntityRelationship;
import net.mca.entity.ai.relationship.Gender;
import net.mca.entity.ai.relationship.RelationshipState;
import net.mca.entity.ai.relationship.RelationshipType;
import net.mca.item.ItemsMCA;
import net.mca.network.s2c.ShowToastRequest;
import net.mca.resources.API;
import net.mca.resources.Rank;
import net.mca.resources.Tasks;
import net.mca.util.NbtHelper;
import net.mca.util.WorldUtils;
import net.minecraft.entity.Entity;
import net.minecraft.entity.damage.DamageSource;
import net.minecraft.entity.mob.MobEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;
import net.minecraft.nbt.NbtList;
import net.minecraft.nbt.NbtString;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.server.world.ServerWorld;
import net.minecraft.text.Text;
import net.minecraft.util.Formatting;
import net.minecraft.util.math.BlockPos;
import net.minecraft.world.PersistentState;
import org.jetbrains.annotations.NotNull;
import org.jetbrains.annotations.Nullable;

import java.util.LinkedList;
import java.util.List;
import java.util.Optional;
import java.util.UUID;

@SuppressWarnings("OptionalUsedAsFieldOrParameterType")
public class PlayerSaveData extends PersistentState implements EntityRelationship {
    private final ServerWorld world;
    private final UUID uuid;

    private Optional<Integer> lastSeenVillage = Optional.empty();

    private boolean entityDataSet;
    private NbtCompound entityData;

    private final List<NbtCompound> inbox = new LinkedList<>();

    public static PlayerSaveData get(ServerPlayerEntity player) {
        return get((ServerWorld) player.getWorld(), player.getUuid());
    }

    public static PlayerSaveData get(ServerWorld world, UUID uuid) {
        return WorldUtils.loadData(world.getServer().getOverworld(), nbt -> new PlayerSaveData(world, uuid, nbt), w -> new PlayerSaveData(world, uuid), "mca_player_" + uuid);
    }

    public static Optional<PlayerSaveData> getIfPresent(ServerWorld world, UUID uuid) {
        return Optional.ofNullable(world.getPersistentStateManager().get(nbt -> new PlayerSaveData(world, uuid, nbt), "mca_player_" + uuid));
    }

    PlayerSaveData(ServerWorld world, UUID uuid) {
        this.world = world;
        this.uuid = uuid;

        resetEntityData();
    }

    PlayerSaveData(ServerWorld world, UUID uuid, NbtCompound nbt) {
        this.world = world;
        this.uuid = uuid;

        lastSeenVillage = nbt.contains("lastSeenVillage", NbtElement.INT_TYPE) ? Optional.of(nbt.getInt("lastSeenVillage")) : Optional.empty();
        entityDataSet = nbt.contains("entityDataSet") && nbt.getBoolean("entityDataSet");

        if (nbt.contains("entityData")) {
            entityData = nbt.getCompound("entityData");
        } else {
            resetEntityData();
        }

        NbtList inbox = nbt.getList("inbox", NbtElement.COMPOUND_TYPE);
        if (inbox != null) {
            this.inbox.clear();
            for (int i = 0; i < inbox.size(); i++) {
                this.inbox.add(inbox.getCompound(i));
            }
        }
    }

    private void resetEntityData() {
        entityData = new NbtCompound();

        VillagerEntityMCA villager = EntitiesMCA.MALE_VILLAGER.get().create(world);
        assert villager != null;
        villager.initializeSkin(true);
        villager.getGenetics().randomize();
        villager.getTraits().randomize();
        villager.getVillagerBrain().randomize();
        ((MobEntity) villager).writeCustomDataToNbt(entityData);
    }

    public boolean isEntityDataSet() {
        return entityDataSet;
    }

    public NbtCompound getEntityData() {
        return entityData;
    }

    public void setEntityDataSet(boolean entityDataSet) {
        this.entityDataSet = entityDataSet;
        markDirty();
    }

    public void setEntityData(NbtCompound entityData) {
        this.entityData = entityData;
        markDirty();
    }

    @Override
    public void onTragedy(DamageSource cause, @Nullable BlockPos burialSite, RelationshipType type, Entity victim) {
        EntityRelationship.super.onTragedy(cause, burialSite, type, victim);

        // send letter of condolence
        if (victim instanceof VillagerEntityMCA victimVillager) {
            sendLetterOfCondolence(victimVillager.getName().getString(),
                    victimVillager.getResidency().getHomeVillage().map(Village::getName).orElse(API.getVillagePool().pickVillageName("village")));
        }
    }

    public void updateLastSeenVillage(VillageManager manager, ServerPlayerEntity self) {
        Optional<Village> prevVillage = getLastSeenVillage(manager);
        Optional<Village> nextVillage = prevVillage
                .filter(v -> v.isWithinBorder(self))
                .or(() -> manager.findNearestVillage(self));

        setLastSeenVillage(self, prevVillage.orElse(null), nextVillage.orElse(null));

        // village rank advancement
        if (nextVillage.isPresent()) {
            Rank rank = Tasks.getRank(nextVillage.get(), self);
            CriterionMCA.RANK.trigger(self, rank);
        }
    }

    public void setLastSeenVillage(ServerPlayerEntity self, Village oldVillage, @Nullable Village newVillage) {
        lastSeenVillage = Optional.ofNullable(newVillage).map(Village::getId);
        markDirty();

        if (oldVillage != newVillage) {
            if (oldVillage != null) {
                onLeave(self, oldVillage);
            }
            if (newVillage != null) {
                onEnter(self, newVillage);
            }
        }
    }

    public Optional<Village> getLastSeenVillage(VillageManager manager) {
        return lastSeenVillage.flatMap(manager::getOrEmpty);
    }

    public Optional<Integer> getLastSeenVillageId() {
        return lastSeenVillage;
    }

    protected void onLeave(PlayerEntity self, Village village) {
        if (Config.getInstance().enterVillageNotification && village.isVillage()) {
            self.sendMessage(Text.translatable("gui.village.left", village.getName()).formatted(Formatting.GOLD), true);
        }
    }

    protected void onEnter(PlayerEntity self, Village village) {
        if (Config.getInstance().enterVillageNotification && village.isVillage()) {
            self.sendMessage(Text.translatable("gui.village.welcome", village.getName()).formatted(Formatting.GOLD), true);
        }
        village.onEnter(world);
    }

    @Override
    public void marry(Entity spouse) {
        EntityRelationship.super.marry(spouse);
        markDirty();
    }

    @Override
    public void endRelationShip(RelationshipState newState) {
        EntityRelationship.super.endRelationShip(newState);
        markDirty();
    }

    @Override
    public ServerWorld getWorld() {
        return world;
    }

    @Override
    public UUID getUUID() {
        return uuid;
    }

    @Override
    public Gender getGender() {
        return Gender.byId(getEntityData().getInt("gender"));
    }

    @Override
    public @NotNull FamilyTreeNode getFamilyEntry() {
        return getFamilyTree().getOrEmpty(uuid).orElseGet(() -> {
            String name = Optional.ofNullable(world.getPlayerByUuid(uuid)).map(p -> p.getName().getString()).orElse("Unnamed Adventurer");
            return getFamilyTree().getOrCreate(uuid, name, getGender(), true);
        });
    }

    public void reset() {
        endRelationShip(RelationshipState.SINGLE);
        markDirty();
    }

    @Override
    public NbtCompound writeNbt(NbtCompound nbt) {
        lastSeenVillage.ifPresent(id -> nbt.putInt("lastSeenVillage", id));
        nbt.put("entityData", entityData);
        nbt.putBoolean("entityDataSet", entityDataSet);
        nbt.put("inbox", NbtHelper.fromList(inbox, v -> v));
        return nbt;
    }

    public void sendMail(NbtCompound nbt) {
        if (Config.getInstance().enableVillagerMailingPlayers) {
            inbox.add(nbt);
        }
        markDirty();
    }

    public boolean hasMail() {
        return !inbox.isEmpty();
    }

    public ItemStack getMail() {
        if (hasMail()) {
            NbtCompound nbt = inbox.remove(0);
            ItemStack stack = new ItemStack(ItemsMCA.LETTER.get(), 1);
            stack.setNbt(nbt);
            return stack;
        } else {
            return null;
        }
    }

    public void sendLetterOfCondolence(String name, String village) {
        sendLetter(List.of("{ \"translate\": \"mca.letter.condolence\", \"with\": [\"" + getFamilyEntry().getName() + "\", \"" + name + "\", \"" + village + "\"] }"));
    }

    public void sendLetter(List<String> lines) {
        NbtList l = new NbtList();
        for (String line : lines) {
            l.add(0, NbtString.of(line));
        }
        NbtCompound nbt = new NbtCompound();
        nbt.put("pages", l);
        sendMail(nbt);

        Optional.ofNullable(world.getPlayerByUuid(uuid)).ifPresent(p -> showMailNotification((ServerPlayerEntity) p));
    }

    public static void showMailNotification(ServerPlayerEntity player) {
        NetworkHandler.sendToPlayer(new ShowToastRequest(
                "server.mail.title",
                "server.mail.description"
        ), player);
    }
}

package net.mca.server.world.data;

import net.mca.Config;
import net.mca.MCA;
import net.mca.advancement.criterion.CriterionMCA;
import net.mca.resources.BuildingTypes;
import net.mca.resources.data.BuildingType;
import net.mca.server.ReaperSpawner;
import net.mca.server.SpawnQueue;
import net.mca.util.NbtHelper;
import net.mca.util.WorldUtils;
import net.minecraft.block.Block;
import net.minecraft.entity.Entity;
import net.minecraft.entity.EntityType;
import net.minecraft.entity.SpawnReason;
import net.minecraft.entity.SpawnRestriction;
import net.minecraft.entity.mob.IllagerEntity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;
import net.minecraft.nbt.NbtList;
import net.minecraft.registry.Registries;
import net.minecraft.server.network.ServerPlayerEntity;
import net.minecraft.server.world.ServerWorld;
import net.minecraft.text.Text;
import net.minecraft.util.Formatting;
import net.minecraft.util.Identifier;
import net.minecraft.util.math.BlockPos;
import net.minecraft.util.math.MathHelper;
import net.minecraft.world.Difficulty;
import net.minecraft.world.Heightmap;
import net.minecraft.world.PersistentState;
import net.minecraft.world.SpawnHelper;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Predicate;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class VillageManager extends PersistentState implements Iterable<Village> {
    private final Map<Integer, Village> villages = new HashMap<>();

    public final Set<BlockPos> cache = ConcurrentHashMap.newKeySet();

    private final List<BlockPos> buildingQueue = new LinkedList<>();

    private int lastBuildingId;
    private int lastVillageId;

    private final ServerWorld world;

    private final ReaperSpawner reapers;

    private int buildingCooldown = 21;

    public static VillageManager get(ServerWorld world) {
        return WorldUtils.loadData(world, nbt -> new VillageManager(world, nbt), VillageManager::new, "mca_villages");
    }

    VillageManager(ServerWorld world) {
        this.world = world;
        reapers = new ReaperSpawner(this);
    }

    VillageManager(ServerWorld world, NbtCompound nbt) {
        this.world = world;
        lastBuildingId = nbt.getInt("lastBuildingId");
        lastVillageId = nbt.getInt("lastVillageId");
        reapers = nbt.contains("reapers", NbtElement.COMPOUND_TYPE) ? new ReaperSpawner(this, nbt.getCompound("reapers")) : new ReaperSpawner(this);

        NbtList villageList = nbt.getList("villages", NbtElement.COMPOUND_TYPE);
        for (int i = 0; i < villageList.size(); i++) {
            Village village = new Village(villageList.getCompound(i), world);
            if (village.getBuildings().isEmpty()) {
                MCA.LOGGER.warn("Empty village detected (" + village.getName() + "), removing...");
                markDirty();
            } else {
                villages.put(village.getId(), village);
            }
        }
    }

    public ReaperSpawner getReaperSpawner() {
        return reapers;
    }

    public Optional<Village> getOrEmpty(int id) {
        return Optional.ofNullable(villages.get(id));
    }

    public boolean removeVillage(int id) {
        if (villages.remove(id) != null) {
            cache.clear();
            return true;
        }
        return false;
    }

    @Override
    public Iterator<Village> iterator() {
        return villages.values().iterator();
    }

    public Stream<Village> findVillages(Predicate<Village> predicate) {
        return villages.values().stream().filter(predicate);
    }

    public Optional<Village> findNearestVillage(Entity entity) {
        BlockPos p = entity.getBlockPos();
        return findVillages(v -> v.isWithinBorder(entity)).min((a, b) -> (int)(a.getCenter().getSquaredDistance(p) - b.getCenter().getSquaredDistance(p)));
    }

    public Optional<Village> findNearestVillage(BlockPos p, int margin) {
        return findVillages(v -> v.isWithinBorder(p, margin)).min((a, b) -> (int)(a.getCenter().getSquaredDistance(p) - b.getCenter().getSquaredDistance(p)));
    }

    public boolean isWithinHorizontalBoundaries(BlockPos p) {
        return villages.values().stream().anyMatch(v -> v.getBox().expand(0, 1000, 0).contains(p));
    }

    @Override
    public NbtCompound writeNbt(NbtCompound nbt) {
        nbt.putInt("lastBuildingId", lastBuildingId);
        nbt.putInt("lastVillageId", lastVillageId);
        nbt.put("villages", NbtHelper.fromList(villages.values(), Village::save));
        nbt.put("reapers", reapers.writeNbt());
        return nbt;
    }

    /**
     * Updates all the villages in the world.
     */
    public void tick() {
        //keep track of where player are currently
        if (world.getTimeOfDay() % 100 == 0) {
            world.getPlayers().forEach(player ->
                    PlayerSaveData.get(player).updateLastSeenVillage(this, player)
            );
        }

        //send bounty hunters
        if (world.getTimeOfDay() % (Config.getInstance().bountyHunterInterval / 10) == 0 && world.getDifficulty() != Difficulty.PEACEFUL) {
            world.getPlayers().forEach(player -> {
                if (world.random.nextInt(10) == 0 && !isWithinHorizontalBoundaries(player.getBlockPos()) && !player.isCreative()) {
                    villages.values().stream()
                            .filter(v -> v.getPopulation() >= 3)
                            .filter(v -> v.getReputation(player) < Config.getInstance().bountyHunterHearts)
                            .min(Comparator.comparingInt(v -> v.getReputation(player)))
                            .ifPresent(buildings -> startBountyHunterWave(player, buildings));
                }
            });
        }

        long time = world.getTime();

        for (Village v : this) {
            v.tick(world, time);
        }

        //process a single building
        if (time % buildingCooldown == 0 && !buildingQueue.isEmpty()) {
            processBuilding(buildingQueue.remove(0));
        }

        reapers.tick(world);
        SpawnQueue.getInstance().tick();
    }

    private void startBountyHunterWave(ServerPlayerEntity player, Village sender) {
        int count = Math.min(30, -sender.getReputation(player) / 100 + 2);

        if (sender.getPopulation() == 0) {
            //the village has been wiped out, lets send one last wave
            sender.cleanReputation();
            sender.resetHearts(player);

            count *= 2;
        } else {
            //slightly increase your reputation
            sender.pushHearts(player, count * 50);
        }

        //trigger advancement
        CriterionMCA.GENERIC_EVENT_CRITERION.trigger(player, "bounty_hunter");

        //spawn the bois
        for (int c = 0; c < count; c++) {
            if (world.random.nextBoolean()) {
                spawnBountyHunter(EntityType.PILLAGER, player);
            } else {
                spawnBountyHunter(EntityType.VINDICATOR, player);
            }
        }

        //warn the player
        player.sendMessage(Text.translatable(sender.getPopulation() == 0 ? "events.bountyHuntersFinal" : "events.bountyHunters", sender.getName()).formatted(Formatting.RED), false);

        //civil entry
        sender.getCivilRegistry().ifPresent(r -> r.addText(Text.translatable("civil_registry.bounty_hunters", player.getName())));
    }

    private <T extends IllagerEntity> void spawnBountyHunter(EntityType<T> t, ServerPlayerEntity player) {
        IllagerEntity pillager = t.create(world);
        if (pillager != null) {
            for (int attempt = 0; attempt < 32; attempt++) {
                float f = this.world.random.nextFloat() * 6.2831855F;
                int x = (int)(player.getX() + MathHelper.cos(f) * 32.0f);
                int z = (int)(player.getZ() + MathHelper.sin(f) * 32.0f);
                int y = world.getTopY(Heightmap.Type.WORLD_SURFACE, x, z);
                BlockPos pos = new BlockPos(x, y, z);
                if (SpawnHelper.canSpawn(SpawnRestriction.Location.ON_GROUND, world, pos, t)) {
                    pillager.setPosition(x, y, z);
                    pillager.setTarget(player);
                    WorldUtils.spawnEntity(world, pillager, SpawnReason.EVENT);
                    break;
                }
            }
        }
    }

    //adds a potential block to the processing queue
    public void reportBuilding(BlockPos pos) {
        //mark in cache
        cache.add(pos);

        buildingQueue.add(pos);
    }

    public Building.validationResult processBuilding(BlockPos pos) {
        return processBuilding(pos, false, true);
    }

    //checks weather the given block contains a grouped building block, e.g., a town bell or gravestone
    private BuildingType getGroupedBuildingType(BlockPos pos) {
        Block block = world.getBlockState(pos).getBlock();
        Identifier blockId = Registries.BLOCK.getId(block);
        for (BuildingType bt : BuildingTypes.getInstance()) {
            if (bt.grouped() && bt.matchesBlock(blockId)) {
                return bt;
            }
        }
        return null;
    }

    //returns the scan-source blocks of all buildings, used to check for overlaps
    private Set<BlockPos> getBlockedSet(Village village) {
        return village.getBuildings().values().stream()
                .filter(b -> !b.getBuildingType().grouped())
                .map(Building::getSourceBlock)
                .collect(Collectors.toSet());
    }

    //processed a building at given position
    public Building.validationResult processBuilding(BlockPos pos, boolean enforce, boolean strictScan) {
        //find the closest village
        Optional<Village> optionalVillage = findNearestVillage(pos, Village.MERGE_MARGIN);

        //check if this might be a grouped building
        BuildingType groupedBuildingType = getGroupedBuildingType(pos);

        //block existing buildings to prevent overlaps
        Set<BlockPos> blocked = new HashSet<>();

        //look for existing building
        boolean found = false;
        List<Integer> toRemove = new LinkedList<>();
        if (optionalVillage.isPresent()) {
            Village village = optionalVillage.get();

            blocked = getBlockedSet(village);
            if (groupedBuildingType != null) {
                String name = groupedBuildingType.name();
                double range = groupedBuildingType.mergeRange() * groupedBuildingType.mergeRange();

                //add POI to the nearest one
                Optional<Building> building = village.getBuildings().values().stream()
                        .filter(b -> b.getType().equals(name))
                        .min((a, b) -> (int)(a.getCenter().getSquaredDistance(pos) - b.getCenter().getSquaredDistance(pos)))
                        .filter(b -> b.getCenter().getSquaredDistance(pos) < range);

                if (building.isPresent()) {
                    found = true;
                    building.get().addPOI(world, pos);
                    markDirty();
                }
            } else {
                //verify affected buildings
                for (Building b : village.getBuildings().values()) {
                    if (b.containsPos(pos)) {
                        if (!enforce) {
                            found = true;
                        }
                        if ((enforce || world.getTime() - b.getLastScan() > Building.SCAN_COOLDOWN) && b.validateBuilding(world, blocked) != Building.validationResult.SUCCESS) {
                            toRemove.add(b.getId());
                        }
                    }
                }
            }

            //remove buildings, which became invalid for whatever reason
            for (int id : toRemove) {
                village.removeBuilding(id);
                markDirty();
            }

            //village is empty
            if (village.getBuildings().isEmpty()) {
                villages.remove(village.getId());
                optionalVillage = Optional.empty();
                markDirty();
            }
        }

        //add a new building, if no overlap has been found or the player enforced a full add
        if (!found && !blocked.contains(pos)) {
            //create new village
            Village village = optionalVillage.orElse(new Village(lastVillageId++, world));

            //create new building
            Building building = new Building(pos, strictScan);
            if (groupedBuildingType != null) {
                //add initial poi
                building.setType(groupedBuildingType.name());
                building.addPOI(world, pos);
            } else {
                //check its boundaries, count the blocks, etc
                Building.validationResult result = building.validateBuilding(world, blocked);
                if (result == Building.validationResult.SUCCESS) {
                    //the building is valid, but might be identical to an old one with an existing one
                    if (village.getBuildings().values().stream().anyMatch(b -> b.isIdentical(building))) {
                        return Building.validationResult.IDENTICAL;
                    }
                } else {
                    //not valid
                    return result;
                }
            }

            //add to building list
            villages.put(village.getId(), village);
            building.setId(lastBuildingId++);
            village.getBuildings().put(building.getId(), building);
            village.calculateDimensions();

            //attempt to merge
            villages.values().stream()
                    .filter(v -> v != village)
                    .filter(v -> v.getBox().expand(Village.MERGE_MARGIN).intersects(village.getBox()))
                    .findAny()
                    .ifPresent(v -> {
                                if (v.getPopulation() > village.getPopulation()) {
                                    merge(v, village);
                                    villages.remove(village.getId());
                                } else {
                                    merge(village, v);
                                    villages.remove(v.getId());
                                }
                            }
                    );

            markDirty();
        }

        return Building.validationResult.SUCCESS;
    }

    public void setBuildingCooldown(int buildingCooldown) {
        this.buildingCooldown = buildingCooldown;
    }

    public void merge(Village into, Village from) {
        into.merge(from);
    }
}

package net.mca.util;

import net.minecraft.entity.Entity;
import net.minecraft.entity.EquipmentSlot;
import net.minecraft.inventory.Inventory;
import net.minecraft.inventory.SimpleInventory;
import net.minecraft.item.*;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtList;
import org.jetbrains.annotations.Nullable;

import java.util.Comparator;
import java.util.Optional;
import java.util.function.Predicate;
import java.util.stream.IntStream;
import java.util.stream.Stream;

public interface InventoryUtils {

    static Stream<ItemStack> stream(Inventory inventory) {
        return IntStream.range(0, inventory.size()).mapToObj(inventory::getStack);
    }

    static int getFirstSlotContainingItem(Inventory inv, Predicate<ItemStack> predicate) {
        for (int i = 0; i < inv.size(); i++) {
            ItemStack stack = inv.getStack(i);
            if (!predicate.test(stack)) continue;
            return i;
        }
        return -1;
    }

    static boolean contains(Inventory inv, Class<?> clazz) {
        for (int i = 0; i < inv.size(); ++i) {
            final ItemStack stack = inv.getStack(i);
            final Item item = stack.getItem();

            if (item.getClass() == clazz) return true;
        }
        return false;
    }

    /**
     * Gets the best quality (max damage) item of the specified type that is in the inventory.
     *
     * @param type The class of item that will be returned.
     *
     * @return The item stack containing the item of the specified type with the highest max damage.
     */
    static ItemStack getBestItemOfType(Inventory inv, @Nullable Class<?> type) {
        return type == null ? ItemStack.EMPTY : inv.getStack(getBestItemOfTypeSlot(inv, type));
    }

    static int getBestItemOfTypeSlot(Inventory inv, Class<?> type) {
        int highestMaxDamage = 0;
        int best = -1;

        for (int i = 0; i < inv.size(); ++i) {
            ItemStack stackInInventory = inv.getStack(i);

            final String itemClassName = stackInInventory.getItem().getClass().getName();

            if (itemClassName.equals(type.getName()) && highestMaxDamage < stackInInventory.getMaxDamage()) {
                highestMaxDamage = stackInInventory.getMaxDamage();
                best = i;
            }
        }

        return best;
    }

    static Optional<ItemStack> getBestArmor(Inventory inv, EquipmentSlot slot) {
        return stream(inv)
                .filter(s -> s.getItem() instanceof ArmorItem)
                .filter(s -> ((ArmorItem)s.getItem()).getSlotType() == slot)
                .max(Comparator.comparingDouble(s -> ((ArmorItem)s.getItem()).getProtection()));
    }

    static Optional<ItemStack> getBestSword(Inventory inv) {
        return stream(inv)
                .filter(s -> s.getItem() instanceof SwordItem)
                .max(Comparator.comparingDouble(s -> ((SwordItem)s.getItem()).getAttackDamage()));
    }

    static Optional<ItemStack> getBestRanged(Inventory inv) {
        return stream(inv)
                .filter(s -> s.getItem() instanceof RangedWeaponItem)
                .max(Comparator.comparingDouble(s -> s.getItem().getMaxDamage()));
    }

    static void dropAllItems(Entity entity, Inventory inv) {
        for (int i = 0; i < inv.size(); i++) {
            ItemStack stack = inv.getStack(i);
            entity.dropStack(stack, 1.0F);
        }
        inv.clear();
    }

    static void load(Inventory inv, NbtList tagList) {
        for (int i = 0; i < inv.size(); ++i) {
            inv.setStack(i, ItemStack.EMPTY);
        }

        for (int i = 0; i < tagList.size(); ++i) {
            NbtCompound nbt = tagList.getCompound(i);
            int slot = nbt.getByte("Slot") & 255;

            if (slot < inv.size()) {
                inv.setStack(slot, ItemStack.fromNbt(nbt));
            }
        }
    }

    static NbtList save(Inventory inv) {
        NbtList tagList = new NbtList();

        for (int i = 0; i < inv.size(); ++i) {
            ItemStack itemstack = inv.getStack(i);

            if (itemstack != ItemStack.EMPTY) {
                NbtCompound nbt = new NbtCompound();
                nbt.putByte("Slot", (byte)i);
                itemstack.setNbt(nbt);
                tagList.add(nbt);
            }
        }

        return tagList;
    }

    static void saveToNBT(SimpleInventory inv, NbtCompound nbt) {
        nbt.put("Inventory", inv.toNbtList());
    }

    static void readFromNBT(SimpleInventory inv, NbtCompound nbt) {
        inv.readNbtList(nbt.getList("Inventory", 10));
    }
}

package net.mca.util;

import com.mojang.datafixers.util.Pair;
import net.mca.MCA;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;
import net.minecraft.nbt.NbtList;
import net.minecraft.nbt.NbtOps;
import net.minecraft.util.math.GlobalPos;

import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.function.BiFunction;
import java.util.function.Function;
import java.util.function.Supplier;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public interface NbtHelper {

    @SuppressWarnings("unchecked")
    static <T extends NbtElement> T computeIfAbsent(NbtCompound nbt, String key, int type, Supplier<T> factory) {
        if (!nbt.contains(key, type)) {
            nbt.put(key, factory.get());
        }
        return (T)nbt.get(key);
    }

    static NbtCompound copyTo(NbtCompound from, NbtCompound to) {
        from.getKeys().forEach(key -> to.put(key, from.get(key)));
        return to;
    }

    static <V> List<V> toList(NbtElement nbt, Function<NbtElement, V> valueMapper) {
        return toStream(nbt, valueMapper).collect(Collectors.toList());
    }

    static <V> Stream<V> toStream(NbtElement nbt, Function<NbtElement, V> valueMapper) {
        return ((NbtList)nbt).stream().map(valueMapper);
    }

    static <K, V> Map<K, V> toMap(NbtCompound nbt, Function<String, K> keyMapper, Function<NbtElement, V> valueMapper) {
        return toMap(nbt, keyMapper, (k, e) -> valueMapper.apply(e));
    }

    static <K, V> Map<K, V> toMap(NbtCompound nbt, Function<String, K> keyMapper, BiFunction<K, NbtElement, V> valueMapper) {
        return nbt.getKeys().stream()
                .map(e -> {
                    K k = keyMapper.apply(e);
                    if (k == null) return null;
                    V v = valueMapper.apply(k, nbt.get(e));
                    if (v == null) return null;
                    return k == null ? null : new Pair<>(k, v);
                })
                .filter(Objects::nonNull)
                .collect(Collectors.toMap(Pair::getFirst, Pair::getSecond)
                );
    }

    static <V> NbtList fromList(Iterable<V> list, Function<V, NbtElement> valueMapper) {
        NbtList output = new NbtList();
        list.forEach(item -> {
            output.add(valueMapper.apply(item));
        });
        return output;
    }

    static <K, V> NbtCompound fromMap(NbtCompound output, Map<K, V> map, Function<K, String> keyMapper, Function<V, NbtElement> valueMapper) {
        map.forEach((key, value) -> output.put(keyMapper.apply(key), valueMapper.apply(value)));
        return output;
    }

    static NbtElement encodeGlobalPosition(GlobalPos v) {
        return GlobalPos.CODEC.encodeStart(NbtOps.INSTANCE, v).resultOrPartial(MCA.LOGGER::error).orElseThrow();
    }

    static GlobalPos decodeGlobalPos(NbtElement element) {
        return GlobalPos.CODEC.parse(NbtOps.INSTANCE, element).resultOrPartial(MCA.LOGGER::error).orElse(null);
    }
}

package net.mca.util;

import com.mojang.datafixers.util.Pair;
import net.minecraft.entity.Entity;
import net.minecraft.entity.SpawnReason;
import net.minecraft.entity.mob.MobEntity;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.registry.Registry;
import net.minecraft.registry.RegistryKeys;
import net.minecraft.registry.entry.RegistryEntry;
import net.minecraft.registry.entry.RegistryEntryList;
import net.minecraft.registry.tag.TagKey;
import net.minecraft.server.world.ChunkLevelType;
import net.minecraft.server.world.ServerChunkManager;
import net.minecraft.server.world.ServerWorld;
import net.minecraft.util.Identifier;
import net.minecraft.util.math.*;
import net.minecraft.world.PersistentState;
import net.minecraft.world.ServerWorldAccess;
import net.minecraft.world.World;
import net.minecraft.world.chunk.WorldChunk;
import net.minecraft.world.gen.structure.Structure;

import java.util.List;
import java.util.Optional;
import java.util.function.Function;

public interface WorldUtils {
    static List<Entity> getCloseEntities(World world, Entity e, double range) {
        Vec3d pos = e.getPos();
        return world.getOtherEntities(e, new Box(pos, pos).expand(range));
    }

    static <T extends Entity> List<T> getCloseEntities(World world, Entity e, double range, Class<T> c) {
        return getCloseEntities(world, e.getPos(), range, c);
    }

    static <T extends Entity> List<T> getCloseEntities(World world, Vec3d pos, double range, Class<T> c) {
        return world.getNonSpectatingEntities(c, new Box(pos, pos).expand(range));
    }

    static <T extends PersistentState> T loadData(ServerWorld world, Function<NbtCompound, T> loader, Function<ServerWorld, T> factory, String dataId) {
        return world.getPersistentStateManager().getOrCreate(loader, () -> factory.apply(world), dataId);
    }

    static void spawnEntity(World world, MobEntity entity, SpawnReason reason) {
        entity.initialize((ServerWorldAccess) world, world.getLocalDifficulty(entity.getBlockPos()), reason, null, null);
        world.spawnEntity(entity);
    }

    //a wrapper for the unnecessary complex query provided by minecraft
    static Optional<BlockPos> getClosestStructurePosition(ServerWorld world, BlockPos center, Identifier structure, int radius) {
        Registry<Structure> registry = world.getRegistryManager().get(RegistryKeys.STRUCTURE);
        Structure feature = registry.get(structure);
        Optional<RegistryEntry.Reference<Structure>> entry = registry.getEntry(registry.getRawId(feature));
        if (entry.isPresent()) {
            RegistryEntryList.Direct<Structure> of = RegistryEntryList.of(entry.get());
            Pair<BlockPos, RegistryEntry<Structure>> pair = world.getChunkManager().getChunkGenerator().locateStructure(world, of, center, radius, false);
            return pair == null ? Optional.empty() : Optional.ofNullable(pair.getFirst());
        } else {
            return Optional.empty();
        }
    }

    static Optional<BlockPos> getClosestStructurePosition(ServerWorld world, BlockPos center, TagKey<Structure> tag, int radius) {
        Registry<Structure> registry = world.getRegistryManager().get(RegistryKeys.STRUCTURE);
        var entryList = registry.getEntryList(tag);
        if (entryList.isPresent()) {
            var chunkGenerator = world.getChunkManager().getChunkGenerator();
            Pair<BlockPos, RegistryEntry<Structure>> pair = chunkGenerator.locateStructure(world, entryList.get(), center, radius, false);
            return pair == null ? Optional.empty() : Optional.ofNullable(pair.getFirst());
        } else {
            return Optional.empty();
        }
    }

    static boolean isChunkLoaded(World world, Vec3i pos) {
        if (world instanceof ServerWorld serverWorld) {
            return isChunkLoaded(serverWorld, pos);
        }
        return false;
    }

    static boolean isChunkLoaded(ServerWorld world, Vec3i pos) {
        return isChunkLoaded(world, new BlockPos(pos));
    }

    static boolean isChunkLoaded(ServerWorld world, BlockPos pos) {
        ChunkPos chunkPos = new ChunkPos(pos);
        WorldChunk worldChunk = world.getChunkManager().getWorldChunk(chunkPos.x, chunkPos.z);
        if (worldChunk != null) {
            return worldChunk.getLevelType() == ChunkLevelType.ENTITY_TICKING && world.isChunkLoaded(chunkPos.toLong());
        }
        return false;
    }

    static boolean isAreaLoaded(ServerWorld world, ChunkPos pos, int radius) {
        ServerChunkManager chunkManager = world.getChunkManager();
        for (int x = -radius; x <= radius; x++) {
            for (int z = -radius; z <= radius; z++) {
                if (!chunkManager.isChunkLoaded(pos.x + x, pos.z + z)) {
                    return false;
                }
            }
        }
        return true;
    }
}

package net.mca.util.network.datasync;

import net.minecraft.entity.Entity;
import net.minecraft.entity.data.TrackedData;
import net.minecraft.nbt.NbtCompound;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import java.util.stream.Stream;

public class CDataManager<E extends Entity> {
    private final List<Entry<E, ?, ?>> params;

    private final Map<CParameter<?, ?>, Entry<E, ?, ?>> forwardLookup = new HashMap<>();
    private final Map<TrackedData<?>, Entry<E, ?, ?>> backwardLookup = new HashMap<>();

    private CDataManager(List<Entry<E, ?, ?>> params) {
        this.params = params;
        params.forEach(param -> {
            forwardLookup.put(param.parameter, param);
            backwardLookup.put(param.data, param);
        });
    }

    public boolean isParam(CParameter<?, ?> parameter, TrackedData<?> data) {
        Entry<E, ?, ?> entry = backwardLookup.get(data);
        return entry != null && entry.parameter == parameter;
    }

    @SuppressWarnings({"unchecked", "RedundantSuppression"})
    public <T, TrackedType> T get(E entity, CParameter<T, TrackedType> parameter) {
        //noinspection RedundantCast
        return parameter.get(((Entry<E, T, TrackedType>)forwardLookup.get(parameter)).data, entity.getDataTracker());
    }

    @SuppressWarnings({"unchecked", "RedundantSuppression"})
    public <T, TrackedType> void set(E entity, CParameter<T, TrackedType> parameter, T value) {
        //noinspection RedundantCast
        parameter.set(((Entry<E, T, TrackedType>)forwardLookup.get(parameter)).data, entity.getDataTracker(), value);
    }

    //register all entries
    public void register(E entity) {
        params.forEach(p -> p.register(entity));
    }

    public void load(E entity, NbtCompound nbt) {
        params.forEach(p -> p.load(entity, nbt));
    }

    public void save(E entity, NbtCompound nbt) {
        params.forEach(p -> p.save(entity, nbt));
    }

    public static class Builder<E extends Entity> {
        private final Class<E> type;
        private final List<Entry<E, ?, ?>> params = new ArrayList<>();

        public Builder(Class<E> type) {
            this.type = type;
        }

        public Builder<E> addAll(CParameter<?, ?> ...params) {
            Stream.of(params).map(p -> new Entry<>(type, p)).forEach(this.params::add);
            return this;
        }

        public Builder<E> add(Function<Builder<E>, Builder<E>> subType) {
            return subType.apply(this);
        }

        public CDataManager<E> build() {
            return new CDataManager<>(params);
        }
    }

    private static class Entry<E extends Entity, T, TrackedType> {
        CParameter<T, TrackedType> parameter;
        TrackedData<TrackedType> data;

        public Entry(Class<E> type, CParameter<T, TrackedType> parameter) {
            this.parameter = parameter;
            this.data = parameter.createParam(type);
        }

        public void save(E entity, NbtCompound nbt) {
            parameter.save(nbt, parameter.get(data, entity.getDataTracker()));
        }

        //load entity from nbt
        public void load(E entity, NbtCompound nbt) {
            parameter.set(data, entity.getDataTracker(), parameter.load(nbt));
        }

        public void register(E entity) {
            entity.getDataTracker().startTracking(data, parameter.getDefault());
        }
    }
}

package net.mca.util.network.datasync;

import net.minecraft.entity.Entity;
import net.minecraft.entity.data.DataTracker;
import net.minecraft.entity.data.TrackedData;
import net.minecraft.entity.data.TrackedDataHandler;
import net.minecraft.nbt.NbtCompound;

import java.util.function.BiFunction;

public class CDataParameter<T> implements CParameter<T, T> {
    private final String id;

    private final T defaultValue;

    private final TrackedDataHandler<T> valueType;

    private final BiFunction<NbtCompound, String, T> load;
    private final TriConsumer<NbtCompound, String, ? super T> save;

    protected CDataParameter(String id, TrackedDataHandler<T> valueType, T defaultValue,
            BiFunction<NbtCompound, String, T> load,
            TriConsumer<NbtCompound, String, ? super T> save) {
        this.id = id;
        this.defaultValue = defaultValue;
        this.valueType = valueType;
        this.load = load;
        this.save = save;
    }

    @Override
    public T getDefault() {
        return defaultValue;
    }

    @Override
    public T get(TrackedData<T> param, DataTracker tracker) {
        return tracker.get(param);
    }

    @Override
    public void set(TrackedData<T> param, DataTracker tracker, T v) {
        tracker.set(param, v);
    }

    @Override
    public T load(NbtCompound nbt) {
        return load.apply(nbt, id);
    }

    @Override
    public void save(NbtCompound nbt, T value) {
        save.accept(nbt, id, value);
    }

    @Override
    public TrackedData<T> createParam(Class<? extends Entity> type) {
        return DataTracker.registerData(type, valueType);
    }

    public interface TriConsumer<A, B, C> {
        void accept(A a, B b, C c);
    }
}

package net.mca.util.network.datasync;

import net.minecraft.entity.Entity;
import net.minecraft.entity.data.DataTracker;
import net.minecraft.entity.data.TrackedData;
import net.minecraft.entity.data.TrackedDataHandlerRegistry;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.nbt.NbtElement;
import org.jetbrains.annotations.Nullable;

public class CEnumParameter<T extends Enum<T>> implements CParameter<T, Integer> {
    private final String id;

    @Nullable
    private final T defaultValue;

    private final T[] values;

    public CEnumParameter(String id, Class<T> type, @Nullable T dv) {
        this.id = id;
        this.defaultValue = dv;
        values = type.getEnumConstants();
    }

    @Override
    public Integer getDefault() {
        return defaultValue == null ? -1 : defaultValue.ordinal();
    }

    @Override
    public T get(TrackedData<Integer> param, DataTracker tracker) {
        return fromIndex(tracker.get(param));
    }

    @Override
    public void set(TrackedData<Integer> param, DataTracker tracker, @Nullable T v) {
        tracker.set(param, v == null ? -1 : v.ordinal());
    }

    @Override
    public T load(NbtCompound nbt) {
        return nbt.contains(id, NbtElement.NUMBER_TYPE) ? fromIndex(nbt.getInt(id)) : defaultValue;
    }

    @Override
    public void save(NbtCompound nbt, T value) {
        if (value != null) {
            nbt.putInt(id, value.ordinal());
        }
    }

    private T fromIndex(int index) {
        return index < 0 || index >= values.length ? defaultValue : values[index];
    }

    @Override
    public TrackedData<Integer> createParam(Class<? extends Entity> type) {
        return DataTracker.registerData(type, TrackedDataHandlerRegistry.INTEGER);
    }
}

package net.mca.util.network.datasync;

import net.minecraft.entity.Entity;
import net.minecraft.entity.data.DataTracker;
import net.minecraft.entity.data.TrackedData;
import net.minecraft.entity.data.TrackedDataHandlerRegistry;
import net.minecraft.item.ItemStack;
import net.minecraft.nbt.NbtCompound;
import net.minecraft.util.math.BlockPos;

import java.util.Optional;
import java.util.UUID;

public interface CParameter<T, TrackedType> {
    static CDataParameter<Integer> create(String id, int def) {
        return new CDataParameter<>(id, TrackedDataHandlerRegistry.INTEGER, def, (nbt, key) -> NbtCompoundDefaultGetters.getInt(nbt, key, def), NbtCompound::putInt);
    }

    static CDataParameter<Float> create(String id, float def) {
        return new CDataParameter<>(id, TrackedDataHandlerRegistry.FLOAT, def, (nbt, key) -> NbtCompoundDefaultGetters.getFloat(nbt, key, def), NbtCompound::putFloat);
    }

    static CDataParameter<Boolean> create(String id, boolean def) {
        return new CDataParameter<>(id, TrackedDataHandlerRegistry.BOOLEAN, def, NbtCompound::getBoolean, NbtCompound::putBoolean);
    }

    static CDataParameter<String> create(String id, String def) {
        return new CDataParameter<>(id, TrackedDataHandlerRegistry.STRING, def, (nbt, key) -> NbtCompoundDefaultGetters.getString(nbt, key, def), NbtCompound::putString);
    }

    static CDataParameter<NbtCompound> create(String id, NbtCompound def) {
        return new CDataParameter<>(id, TrackedDataHandlerRegistry.NBT_COMPOUND, def, (nbt, key) -> NbtCompoundDefaultGetters.getCompound(nbt, key, def), NbtCompound::put);
    }

    static CDataParameter<ItemStack> create(String id, ItemStack def) {
    	return new CDataParameter<>("babyItem", TrackedDataHandlerRegistry.ITEM_STACK, ItemStack.EMPTY,
			(nbt, key) -> NbtCompoundDefaultGetters.getItemStack(nbt, key, ItemStack.EMPTY), (nbt, key, stack) ->
			{
				NbtCompound item = new NbtCompound();
				stack.writeNbt(item);
				nbt.put(key, item);
			});
    }

    static CDataParameter<BlockPos> create(String id, BlockPos def) {
        return new CDataParameter<>(id, TrackedDataHandlerRegistry.BLOCK_POS, def,
                (tag, key) -> new BlockPos(
                    tag.getInt(key + "X"),
                    tag.getInt(key + "Y"),
                    tag.getInt(key + "Z")
                ),
                (tag, key, pos) -> {
                    tag.putInt(key + "X", pos.getX());
                    tag.putInt(key + "Y", pos.getY());
                    tag.putInt(key + "Z", pos.getZ());
                });
    }

    static CDataParameter<Optional<UUID>> create(String id, Optional<UUID> def) {
        return new CDataParameter<>(id, TrackedDataHandlerRegistry.OPTIONAL_UUID, def,
                (tag, key) -> tag.containsUuid(key) ? Optional.of(tag.getUuid(key)) : Optional.empty(),
                (tag, key, v) -> v.ifPresent(uuid -> tag.putUuid(key, uuid)));
    }

    @SuppressWarnings("unchecked")
    static <T extends Enum<T>> CEnumParameter<T> create(String id, T def) {
        return new CEnumParameter<>(id, (Class<T>)def.getClass(), def);
    }

    static <T extends Enum<T>> CEnumParameter<T> create(String id, Class<T> type) {
        return new CEnumParameter<>(id, type, null);
    }

    TrackedType getDefault();

    T get(TrackedData<TrackedType> param, DataTracker tracker);

    void set(TrackedData<TrackedType> param, DataTracker tracker, T v);

    T load(NbtCompound nbt);

    void save(NbtCompound nbt, T value);

    TrackedData<TrackedType> createParam(Class<? extends Entity> type);
}

